import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import {
  Heart, User, Menu, X, ChevronDown, Sparkles,
  Search, Building2, Home, TreePine, Store, TrendingUp,
  Phone, LogOut, Settings, BookMarked, Bell,
} from 'lucide-react';
import Logo from './Logo';
import styles from './Navbar.module.css';

/* ── Nav structure with mega-menu items ───────────────────────── */
const NAV_ITEMS = [
  {
    label: 'Buy',
    to: '/search?listingType=Sell',
    sub: [
      { icon: Building2, label: 'Apartments',       desc: 'Ready & under-construction flats', to: '/search?listingType=Sell&propertyType=Apartment' },
      { icon: Home,      label: 'Independent House', desc: 'Villas, bungalows & row houses',   to: '/search?listingType=Sell&propertyType=Independent' },
      { icon: TreePine,  label: 'Plots & Land',      desc: 'NA plots, layouts & farmlands',    to: '/search?listingType=Sell&propertyType=Plot' },
      { icon: Store,     label: 'Commercial',         desc: 'Offices, shops & warehouses',      to: '/search?listingType=Sell&buildingType=Commercial' },
    ],
  },
  {
    label: 'Rent',
    to: '/search?listingType=Rent',
    sub: [
      { icon: Building2, label: 'Apartments',       desc: 'Furnished & semi-furnished flats',  to: '/search?listingType=Rent&propertyType=Apartment' },
      { icon: Home,      label: 'Independent House', desc: 'Standalone houses for families',   to: '/search?listingType=Rent&propertyType=Independent' },
      { icon: Store,     label: 'Office Space',      desc: 'Plug-and-play & co-working',       to: '/search?listingType=Rent&buildingType=Commercial' },
    ],
  },
  {
    label: 'Commercial',
    to: '/search?buildingType=Commercial',
    sub: [
      { icon: TrendingUp, label: 'Pre-Leased',   desc: 'Rental income from day one',       to: '/search?buildingType=Commercial&tag=pre-leased' },
      { icon: Store,      label: 'Retail Shops', desc: 'High-street & mall shops',          to: '/search?buildingType=Commercial&propertyType=Shop' },
      { icon: Building2,  label: 'Offices',      desc: 'Grade A corporate offices',         to: '/search?buildingType=Commercial&propertyType=Office' },
    ],
  },
  { label: 'Sell', to: '/post-property', cta: true },
];

/* ── Scroll threshold for shrink effect ──────────────────────── */
const SCROLL_THRESHOLD = 60;

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate  = useNavigate();
  const location  = useLocation();

  const [menuOpen,       setMenuOpen]       = useState(false);
  const [userDropOpen,   setUserDropOpen]   = useState(false);
  const [activeMega,     setActiveMega]     = useState(null); // label of open mega-menu
  const [scrolled,       setScrolled]       = useState(false);

  const dropRef  = useRef(null);
  const megaRef  = useRef(null);
  const megaTimer = useRef(null);

  /* Scroll shrink effect */
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > SCROLL_THRESHOLD);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  /* Close user dropdown on outside click */
  useEffect(() => {
    const handler = (e) => {
      if (dropRef.current && !dropRef.current.contains(e.target)) setUserDropOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  /* Mega-menu hover helpers — delayed close to avoid flicker */
  const openMega  = useCallback((label) => {
    clearTimeout(megaTimer.current);
    setActiveMega(label);
  }, []);

  const closeMega = useCallback(() => {
    megaTimer.current = setTimeout(() => setActiveMega(null), 140);
  }, []);

  const keepMega  = useCallback(() => {
    clearTimeout(megaTimer.current);
  }, []);

  /* Hide navbar on certain pages */
  if (location.pathname.startsWith('/property/') || location.pathname === '/post-property') {
    return null;
  }

  const isActive = (item) =>
    item.to.includes('?')
      ? location.pathname === '/search' && location.search.includes(item.to.split('?')[1])
      : location.pathname === item.to;

  return (
    <>
      {/* ── Top announcement ticker ──────────────────────────── */}
      <div className={styles.ticker}>
        <div className={styles.tickerInner}>
          <span className={styles.tickerDot} />
          <span>🏠 &nbsp;New listings added today · Zero brokerage options available · RERA-verified projects</span>
        </div>
      </div>

      <header className={`${styles.header} ${scrolled ? styles.headerScrolled : ''}`}>
        <div className={styles.inner}>

          {/* ── Logo ─────────────────────────────────────────── */}
          <Link to="/" className={styles.brand} title="ProBridge – We Connect World of Real Estate">
            <Logo size="md" showTagline={true} />
          </Link>

          {/* ── Vertical separator ───────────────────────────── */}
          <div className={styles.sep} />

          {/* ── Desktop Nav ──────────────────────────────────── */}
          <nav className={styles.nav} role="navigation" aria-label="Main navigation">
            {NAV_ITEMS.map((item) => {
              const active = isActive(item);
              const hasSub = item.sub?.length > 0;

              if (item.cta) {
                return (
                  <Link key={item.label} to={item.to} className={styles.navCta}>
                    <Sparkles size={13} className={styles.ctaSparkle} />
                    {item.label} Free
                  </Link>
                );
              }

              return (
                <div
                  key={item.label}
                  className={styles.navItemWrap}
                  onMouseEnter={() => hasSub && openMega(item.label)}
                  onMouseLeave={closeMega}
                >
                  <Link
                    to={item.to}
                    className={`${styles.navLink} ${active ? styles.navLinkActive : ''}`}
                    aria-expanded={activeMega === item.label}
                  >
                    {item.label}
                    {hasSub && (
                      <ChevronDown
                        size={13}
                        className={`${styles.chevron} ${activeMega === item.label ? styles.chevronOpen : ''}`}
                      />
                    )}
                    {active && <span className={styles.activeDot} />}
                  </Link>

                  {/* Mega-menu panel */}
                  {hasSub && activeMega === item.label && (
                    <div
                      className={styles.megaMenu}
                      onMouseEnter={keepMega}
                      onMouseLeave={closeMega}
                      ref={megaRef}
                    >
                      <div className={styles.megaHeader}>
                        <span className={styles.megaLabel}>Browse {item.label}</span>
                        <Link to={item.to} className={styles.megaSeeAll}>See all →</Link>
                      </div>
                      <div className={styles.megaGrid}>
                        {item.sub.map((s) => {
                          const Icon = s.icon;
                          return (
                            <Link
                              key={s.label}
                              to={s.to}
                              className={styles.megaItem}
                              onClick={() => setActiveMega(null)}
                            >
                              <div className={styles.megaIconWrap}>
                                <Icon size={18} className={styles.megaIcon} strokeWidth={1.8} />
                              </div>
                              <div>
                                <div className={styles.megaItemLabel}>{s.label}</div>
                                <div className={styles.megaItemDesc}>{s.desc}</div>
                              </div>
                            </Link>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </nav>

          {/* ── Spacer ───────────────────────────────────────── */}
          <div className={styles.spacer} />

          {/* ── Right cluster ────────────────────────────────── */}
          <div className={styles.rightCluster}>

            {/* Quick search icon */}
            <button
              className={styles.iconBtn}
              onClick={() => navigate('/search')}
              title="Search properties"
              aria-label="Search"
            >
              <Search size={17} strokeWidth={2.2} />
            </button>

            {/* Shortlisted / Saved */}
            <Link to="/saved" className={styles.iconBtn} title="Shortlisted Properties" aria-label="Saved">
              <Heart size={17} strokeWidth={2.2} />
              <span className={styles.iconBtnLabel}>Saved</span>
            </Link>

            {/* Divider */}
            <div className={styles.rightSep} />

            {/* User pill */}
            <div className={styles.userWrap} ref={dropRef}>
              {user ? (
                <>
                  <button
                    type="button"
                    className={styles.userPill}
                    onClick={() => setUserDropOpen((o) => !o)}
                    aria-haspopup="true"
                    aria-expanded={userDropOpen}
                  >
                    {user.photo ? (
                      <img src={user.photo} alt={user.name} className={styles.userAvatar} />
                    ) : (
                      <span className={styles.userInitial}>
                        {user.name ? user.name[0].toUpperCase() : 'U'}
                      </span>
                    )}
                    <span className={styles.userName}>
                      {user.name ? user.name.split(' ')[0] : 'User'}
                    </span>
                    <ChevronDown size={13} className={`${styles.pillChev} ${userDropOpen ? styles.pillChevOpen : ''}`} />
                  </button>

                  {userDropOpen && (
                    <div className={styles.userDrop}>
                      {/* Header */}
                      <div
                        className={styles.dropHead}
                        onClick={() => { navigate('/account'); setUserDropOpen(false); }}
                      >
                        <div className={styles.dropAvatarLg}>
                          {user.photo
                            ? <img src={user.photo} alt={user.name} className={styles.dropAvatarImg} />
                            : <span className={styles.dropInitialLg}>{user.name?.[0]?.toUpperCase() || 'U'}</span>
                          }
                        </div>
                        <div>
                          <div className={styles.dropName}>{user.name}</div>
                          <div className={styles.dropEmail}>{user.email}</div>
                          <span className={styles.dropViewProfile}>View Profile →</span>
                        </div>
                      </div>

                      <div className={styles.dropDivider} />

                      <Link to="/account"              className={styles.dropItem} onClick={() => setUserDropOpen(false)}>
                        <Settings size={14} className={styles.dropIcon} /> My Account
                      </Link>
                      <Link to="/account?tab=listings" className={styles.dropItem} onClick={() => setUserDropOpen(false)}>
                        <BookMarked size={14} className={styles.dropIcon} /> My Listings
                      </Link>
                      <Link to="/saved"                className={styles.dropItem} onClick={() => setUserDropOpen(false)}>
                        <Heart size={14} className={styles.dropIcon} /> Shortlisted
                      </Link>

                      <div className={styles.dropDivider} />

                      <button
                        type="button"
                        className={`${styles.dropItem} ${styles.dropLogout}`}
                        onClick={() => { logout(); setUserDropOpen(false); navigate('/'); }}
                      >
                        <LogOut size={14} className={styles.dropIcon} /> Sign Out
                      </button>
                    </div>
                  )}
                </>
              ) : (
                <>
                  <button
                    type="button"
                    className={styles.userPill}
                    onClick={() => setUserDropOpen((o) => !o)}
                    aria-haspopup="true"
                    aria-expanded={userDropOpen}
                  >
                    <span className={styles.guestCircle}>
                      <User size={15} strokeWidth={2.2} />
                    </span>
                    <span className={styles.userName}>Login</span>
                    <ChevronDown size={13} className={`${styles.pillChev} ${userDropOpen ? styles.pillChevOpen : ''}`} />
                  </button>

                  {userDropOpen && (
                    <div className={styles.userDrop}>
                      <div className={styles.guestDropHead}>
                        <div className={styles.guestDropTitle}>Welcome to ProBridge</div>
                        <div className={styles.guestDropSub}>Sign in to save properties & get personalised recommendations</div>
                      </div>
                      <div className={styles.guestDropBtns}>
                        <Link to="/login"    className={styles.guestLoginBtn} onClick={() => setUserDropOpen(false)}>Sign In</Link>
                        <Link to="/register" className={styles.guestRegBtn}   onClick={() => setUserDropOpen(false)}>Register Free</Link>
                      </div>
                    </div>
                  )}
                </>
              )}
            </div>

            {/* Post property CTA — desktop only shown as extra prominent button */}
            <Link to="/post-property" className={styles.postBtn}>
              <Sparkles size={13} className={styles.postSparkle} />
              Post Property
            </Link>

            {/* Mobile hamburger */}
            <button
              type="button"
              className={styles.hamburger}
              onClick={() => setMenuOpen((o) => !o)}
              aria-label="Toggle navigation menu"
              aria-expanded={menuOpen}
            >
              {menuOpen ? <X size={22} strokeWidth={2.2} /> : <Menu size={22} strokeWidth={2.2} />}
            </button>
          </div>
        </div>

        {/* ── Mobile Drawer ──────────────────────────────────── */}
        {menuOpen && (
          <div className={styles.mobileMenu} role="dialog" aria-modal="true" aria-label="Mobile navigation">
            {/* Nav links */}
            {NAV_ITEMS.map((item) => (
              <Link
                key={item.label}
                to={item.to}
                className={`${styles.mobileLink} ${item.cta ? styles.mobileLinkCta : ''}`}
                onClick={() => setMenuOpen(false)}
              >
                {item.label}
                {item.cta && <span className={styles.mobileFreeTag}>FREE</span>}
              </Link>
            ))}

            <div className={styles.mobileDivider} />

            {user ? (
              <>
                <div className={styles.mobileUser}>
                  <div className={styles.mobileUserInitial}>
                    {user.name?.[0]?.toUpperCase() || 'U'}
                  </div>
                  <div>
                    <div className={styles.mobileUserName}>{user.name}</div>
                    <div className={styles.mobileUserEmail}>{user.email}</div>
                  </div>
                </div>
                <Link to="/account"              className={styles.mobileLink} onClick={() => setMenuOpen(false)}>My Account</Link>
                <Link to="/account?tab=listings" className={styles.mobileLink} onClick={() => setMenuOpen(false)}>My Listings</Link>
                <Link to="/saved"                className={styles.mobileLink} onClick={() => setMenuOpen(false)}>Shortlisted</Link>
                <div className={styles.mobileDivider} />
                <button
                  type="button"
                  className={`${styles.mobileLink} ${styles.mobileLinkLogout}`}
                  onClick={() => { logout(); setMenuOpen(false); navigate('/'); }}
                >
                  Sign Out
                </button>
              </>
            ) : (
              <>
                <Link to="/login"    className={styles.mobileLink} onClick={() => setMenuOpen(false)}>Login</Link>
                <Link to="/register" className={styles.mobileLink} onClick={() => setMenuOpen(false)}>Register Free</Link>
              </>
            )}

            <div className={styles.mobilePostWrap}>
              <Link to="/post-property" className={styles.mobilePostBtn} onClick={() => setMenuOpen(false)}>
                <Sparkles size={14} />
                Post Property Free
              </Link>
            </div>
          </div>
        )}
      </header>
    </>
  );
}
